insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-266', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'If $E_a = 57.4\ \mathrm{kJ\ mol^{-1}}$, the factor by which $k$ grows when $T$ goes from 300 K to 310 K is nearest', '["2","10","0.5","100"]'::jsonb, 0, '$\log(k_2/k_1) = (57400/19.15)(10/93000) \approx 0.32$, so $k_2/k_1 \approx 2$. This is the familiar “about double per 10 K” case.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'arrhenius-ea') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
